typedef int (*PluginFunc)(int val);

int handle_A(int v) { return v + 10; }
int handle_B(int v) { return v * 2; }

// Array of function pointers (Dispatch Table)
PluginFunc PluginList[] = {
    &handle_A,
    handle_B, // Address-of operator often optional
    NULL
};

enum Index { A, B };

int input = 5;
// Invocation: PluginList[index](arguments)
int output = PluginList[B](input); // output = 10

// Dynamic selection
if (PluginList[A]) {
    PluginList[A](input);
}
